import { useRef, type FC } from 'react'
import PopupWrap, { type PopupRefProps } from '../PopupWrap'
import Icon from '../../Common/Icon'
import warning from '../../../assets/icons/powermate/info/pro_info_warning.svg'

interface PopupProps {
    open: boolean
    onClose: () => void
    onCheck: () => void
    onConfirm: () => void
}

const PowermateCompatibilityWarningPopup: FC<PopupProps> = ({ open, onClose, onCheck, onConfirm }) => {
    const wrap = useRef<PopupRefProps>(null)

    const handleClose = () => {
        wrap?.current?.close(() => onClose())
    }

    return (
        <PopupWrap
            ref={wrap}
            id="powermate-compatibility-warning-popup"
            className="compatibility-dialog compatibility-warning-dialog"
            backgroundType="color"
            background="#171717"
            open={open}
            onClose={handleClose}
        >
            <div className="compatibility-dialog-title">
                <Icon className="compatibility-dialog-title-icon" icon={warning} />
                Check Compatibility
            </div>
            <div className="compatibility-dialog-texts">
                <div>The Performance version is compatible <br />with a limited range of vehicles</div>
                <div>To check the compatibility of your Tesla, <br />please provide the VIN number of your vehicle.</div>
            </div>
            <div className="compatibility-dialog-buttons">
                <button type="button" className="compatibility-dialog-button" onClick={onCheck}>Check</button>
                <button type="button" className="compatibility-dialog-button" onClick={onConfirm}>Order Now</button>
            </div>
        </PopupWrap>
    )
}

export default PowermateCompatibilityWarningPopup
